(()=>{'use strict';
// Keep prior users' completed onboarding dismissed; only new installations see the revised flow.
const oldKey='toolbox2-onboarding-seen-v1',key='toolbox2-onboarding-seen-v2';
try{if(localStorage.getItem(oldKey)==='yes'||localStorage.getItem(key)==='yes')return}catch(e){}
const slides=[
{k:'WELCOME ABOARD',h:"You're here. Let's build the next version of you.",p:'Toolbox is your personal maritime companion. Prepare for your next voyage, one step at a time.',art:'assets/toolbox-spanner.png'},
{k:'EVERYTHING IN REACH',h:'Ready for your next voyage.',p:'Organize documents and reminders, use maritime tools, and build your knowledge with reviewers and missions.',art:'assets/toolbox-icon-192.png'},
{k:'MADE FOR LIFE AT SEA',h:'Useful, even offline.',p:'Use supported Toolbox features without signing in. Your locally saved information stays on this device unless you choose to export or share it.',art:'assets/toolbox-spanner.png'},
{k:'YOUR PRIVACY',h:'Your documents. Your control.',p:'Documents saved locally are not automatically sent to your company or crewing office. You decide what to export, print, or share. Keep your phone and backups protected.',art:'assets/toolbox-icon-192.png'},
{k:'OPTIONAL CLOUD',h:'Your Toolbox, your choice.',p:'Bulletproof Cloud is planned for backup and cross-device access. Cloud sign-in and secure sync are not active in this test build. You can use Toolbox without an account.',art:'assets/toolbox-spanner.png'}
];
const overlay=document.createElement('section');overlay.className='tb-intro';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-label','Toolbox introduction');
overlay.innerHTML=`<div class="tb-intro-panel"><div class="tb-intro-top"><div class="tb-intro-brand"><img src="assets/toolbox-icon-192.png" alt=""><span>TOOLBOX</span></div><button type="button" class="tb-intro-skip" id="tbIntroSkip">Skip</button></div><div class="tb-intro-content"><div class="tb-intro-art"><div class="tb-intro-halo"></div><img id="tbIntroImage" src="assets/toolbox-spanner.png" alt="Toolbox illustration"></div><div class="tb-intro-kicker" id="tbIntroKicker"></div><h1 id="tbIntroTitle"></h1><p id="tbIntroText"></p><div class="tb-intro-privacy" id="tbIntroPrivacy" hidden><span>On-device storage</span><span>You control sharing</span><span>Cloud is optional</span></div></div><div class="tb-intro-actions"><div class="tb-intro-dots" id="tbIntroDots" aria-label="Introduction progress"></div><button type="button" class="tb-intro-next" id="tbIntroNext"></button><div class="tb-intro-note" id="tbIntroNote">No account required</div></div></div>`;
document.body.appendChild(overlay);let step=0;const $=id=>overlay.querySelector('#'+id);const previous=document.activeElement;
function draw(){const s=slides[step];$('tbIntroKicker').textContent=s.k;$('tbIntroTitle').textContent=s.h;$('tbIntroText').textContent=s.p;$('tbIntroImage').src=s.art;$('tbIntroPrivacy').hidden=step!==3;$('tbIntroDots').innerHTML=slides.map((_,i)=>`<span class="${i===step?'active':''}"></span>`).join('');$('tbIntroNext').textContent=step===3?'I understand':step===slides.length-1?'Open Toolbox':'Continue';$('tbIntroSkip').hidden=step===slides.length-1;$('tbIntroNote').textContent=step===3?'Local files can still be accessed if your device or backup is compromised.':'No account required';}
function finish(){try{localStorage.setItem(key,'yes');localStorage.setItem(oldKey,'yes')}catch(e){}overlay.remove();previous?.focus?.()}
$('tbIntroNext').addEventListener('click',()=>{if(step<slides.length-1){step++;draw()}else finish()});$('tbIntroSkip').addEventListener('click',finish);
overlay.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();finish()}if(e.key==='Tab'){const f=[...overlay.querySelectorAll('button:not([hidden])')];if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===f.at(-1)){e.preventDefault();f[0].focus()}}});draw();$('tbIntroNext').focus();})();
